import{_ as a,a0 as p,w as s,s as m,ao as r,I as l,x as e,a1 as n,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"一个Linux中用于监控的简易shell脚本 | LCTT x X-CMD","titleTemplate":false,"description":"一个Linux中用于监控的简易shell脚本 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一个Linux中用于监控的简易shell脚本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一个Linux中用于监控的简易shell脚本 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150512 A Shell Script to Monitor Network, Disk Usage, Uptime, Load Average and RAM Usage in Linux","title":"一个Linux中用于监控的简易shell脚本","tag":"201506","desc":""},"relativePath":"201506/20150512 A Shell Script to Monitor Network, Disk Usage, Uptime, Load Average and RAM Usage in Linux.md","filePath":"[post].md"}'),d={name:"201506/20150512 A Shell Script to Monitor Network, Disk Usage, Uptime, Load Average and RAM Usage in Linux.md"};function u(h,t,x,w,L,T){const i=p("Link");return s(),m("div",null,[t[18]||(t[18]=r('<h1 id="一个linux中用于监控的简易shell脚本" tabindex="-1">一个Linux中用于监控的简易shell脚本 <a class="header-anchor" href="#一个linux中用于监控的简易shell脚本" aria-label="Permalink to “一个Linux中用于监控的简易shell脚本”">​</a></h1><p>系统管理员的任务真的很艰难，因为他/她必须监控服务器、用户、日志，还得创建备份，等等等等。对于大多数重复性的任务，大多数管理员都会写一个自动化脚本来日复一日地重复这些任务。这里，我们已经写了一个shell脚本给大家，用来自动化完成系统管理员所要完成的常规任务，这可能在多数情况下，尤其是对于新手而言十分有用，他们能通过该脚本获取到大多数的他们想要的信息，包括系统、网络、用户、负载、内存、主机、内部IP、外部IP、开机时间等。</p><p>我们已经注意并进行了格式化输出（在一定程度上哦）。此脚本不包含任何恶意内容，并且它能以普通用户帐号运行。事实上，我们也推荐你以普通用户运行该脚本，而不是root。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Linux-Health-Monitoring.png" alt="Linux Server Health Monitoring"></p><p><em>监控Linux系统健康的Shell脚本</em></p><p>在保留Tecmint和脚本作者应得荣誉的前提下，可以自由使用/修改/再分发下面代码。我们已经试着在一定程度上自定义了输出结果，除了要求的输出内容外，其它内容都不会生成。我们也已经试着使用了那些Linux系统中通常不使用的变量，这些变量应该是可以随便用的。</p><h4 id="最小系统要求" tabindex="-1">最小系统要求 <a class="header-anchor" href="#最小系统要求" aria-label="Permalink to “最小系统要求”">​</a></h4><p>你所需要的一切，就是一台正常运转的Linux机器。</p><h4 id="依赖性" tabindex="-1">依赖性 <a class="header-anchor" href="#依赖性" aria-label="Permalink to “依赖性”">​</a></h4><p>对于一个标准的Linux发行版，使用此软件包不需任何依赖。此外，该脚本不需要root权限来执行。但是，如果你想要安装，则必须输入一次root密码。</p><h4 id="安全性" tabindex="-1">安全性 <a class="header-anchor" href="#安全性" aria-label="Permalink to “安全性”">​</a></h4><p>我们也关注到了系统安全问题，所以在安装此包时，不需要安装任何额外包，也不需要root访问权限来运行。此外，源代码是采用Apache 2.0许可证发布的，这意味着只要你保留Tecmint的版权，你可以自由地编辑、修改并再分发该代码。</p><h3 id="如何安装和运行脚本" tabindex="-1">如何安装和运行脚本？ <a class="header-anchor" href="#如何安装和运行脚本" aria-label="Permalink to “如何安装和运行脚本？”">​</a></h3>',13)),l("p",null,[t[1]||(t[1]=e("首先，使用",-1)),n(i,{href:"http://www.tecmint.com/10-wget-command-examples-in-linux/"},{default:o(()=>[...t[0]||(t[0]=[e("wget命令",-1)])]),_:1}),t[2]||(t[2]=e("下载监控脚本",-1)),t[3]||(t[3]=l("code",null,"“tecmint_monitor.sh”",-1)),t[4]||(t[4]=e("，给它赋予合适的执行权限。",-1))]),t[19]||(t[19]=r(`<pre><code># wget http://tecmint.com/wp-content/scripts/tecmint_monitor.sh
# chmod 755 tecmint_monitor.sh
</code></pre><p>强烈建议你以普通用户身份安装该脚本，而不是root。安装过程中会询问root密码，并且在需要的时候安装必要的组件。</p><p>要安装“<code>tecmint_monitor.sh</code>”脚本，只需像下面这样使用-i（安装）选项就可以了。</p><pre><code>./tecmint_monitor.sh -i 
</code></pre><p>在提示你输入root密码时输入该密码。如果一切顺利，你会看到像下面这样的安装成功信息。</p><pre><code>Password: 
Congratulations! Script Installed, now run monitor Command
</code></pre><p>安装完毕后，你可以在任何位置，以任何用户调用命令<code>‘monitor’</code>来运行该脚本。如果你不喜欢安装，你需要在每次运行时输入路径。</p><pre><code># ./Path/to/script/tecmint_monitor.sh
</code></pre><p>现在，以任何用户从任何地方运行monitor命令，就是这么简单：</p><pre><code>$ monitor
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/TecMint-Monitor-Script.gif" alt="TecMint Monitor Script in Action"></p><p>你运行命令就会获得下面这些各种各样和系统相关的信息：</p><ul><li>互联网连通性</li><li>操作系统类型</li><li>操作系统名称</li><li>操作系统版本</li><li>架构</li><li>内核版本</li><li>主机名</li><li>内部IP</li><li>外部IP</li><li>域名服务器</li><li>已登录用户</li><li>内存使用率</li><li>交换分区使用率</li><li>磁盘使用率</li><li>平均负载</li><li>系统开机时间</li></ul><p>使用-v（版本）开关来检查安装的脚本的版本。</p><pre><code>$ monitor -v

tecmint_monitor version 0.1
Designed by Tecmint.com
Released Under Apache 2.0 License
</code></pre><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h3><p>该脚本在一些机器上可以开机即用，这一点我已经检查过。相信对于你而言，它也会正常工作。如果你们发现了什么毛病，可以在评论中告诉我。这个脚本还不完善，这仅仅是个开始。从这里开始，你可以将它改进到任何程度。如果你想要编辑脚本，将它带入一个更深的层次，尽管随意去做吧，别忘了给我们应的的荣誉，也别忘了把你更新后的脚本拿出来和我们分享哦，这样，我们也会更新此文来给你应得的荣誉。</p><p>别忘了和我们分享你的想法或者脚本，我们会在这儿帮助你。谢谢你们给予的所有挚爱。继续浏览，不要走开哦。</p><hr>`,19)),l("p",null,[t[6]||(t[6]=e("via: ",-1)),n(i,{href:"http://www.tecmint.com/linux-server-health-monitoring-script/"},{default:o(()=>[...t[5]||(t[5]=[e("http://www.tecmint.com/linux-server-health-monitoring-script/",-1)])]),_:1})]),l("p",null,[t[10]||(t[10]=e("作者：",-1)),n(i,{href:"http://www.tecmint.com/author/avishek/"},{default:o(()=>[...t[7]||(t[7]=[e("Avishek Kumar",-1)])]),_:1}),t[11]||(t[11]=e(" 译者：",-1)),n(i,{href:"https://github.com/GOLinux"},{default:o(()=>[...t[8]||(t[8]=[e("GOLinux",-1)])]),_:1}),t[12]||(t[12]=e(" 校对：",-1)),n(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[15]||(t[15]=e("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原创翻译，",-1)),n(i,{href:"https://linux.cn/"},{default:o(()=>[...t[14]||(t[14]=[e("Linux中国",-1)])]),_:1}),t[17]||(t[17]=e(" 荣誉推出",-1))])])}const c=a(d,[["render",u]]);export{f as __pageData,c as default};
